}

inline int read(int *x){scanf("%d",x);return *x;}
inline void init_case(int *m,int *a,int *b,int *d,int p[]){
	int i;
	scanf("%d%u%d%d%d%d",m,&seed,a,b,&_IO_c,d);
	for(i=1;i<=*m;i++){
		if(randnum()%_IO_c==0)p[i]=-1;
		else p[i]=randnum()%*b;
	}
}

